class Box { public int Raw; public int Value { get => Raw; set => Raw = value; } }
int Pair(int first, int second) => first * 10 + second;
void Main() {
    var a = new Box(); a.Raw = 10; var b = new Box(); b.Raw = 20;
    var target = a;
    Print(target.Value += ((target = b).Value = 3)); Print(a.Raw); Print(b.Raw);
    target = a; Print(target.Value = ((target = b).Value = 7)); Print(a.Raw); Print(b.Raw);
    Print(a.Value += (b.Value += 2)); Print(a.Raw); Print(b.Raw);
    Print(Pair(second: a.Value++, first: ++b.Value)); Print(a.Raw); Print(b.Raw);
}
